// include/slice.class.php, row 1338
"You can use special slice for additional fields definition. There you can write slice ID, which defines the fields.<br>Could be used for data slice, which stores values for user created forms." => "\xC4\xC9\xB2\xC3\xA5\xD5\xA5\xA3\xA1\xBC\xA5\xEB\xA5\xC9\xA4\xCE\xC4\xEA\xB5\xC1\xA4\xCB\xC6\xC3\xCA\xCC\xA4\xCA\xA5\xB9\xA5\xE9\xA5\xA4\xA5\xB9\xA4\xF2\xBB\xC8\xA4\xA8\xA4\xDE\xA4\xB9\xA1\xA3\xA4\xB3\xA4\xB3\xA4\xCB\xA5\xD5\xA5\xA3\xA1\xBC\xA5\xEB\xA5\xC9\xA4\xF2\xC4\xEA\xB5\xC1\xA4\xB9\xA4\xEB\xA5\xB9\xA5\xE9\xA5\xA4\xA5\xB9\xA4\xCE ID \xA4\xF2\xC6\xFE\xCE\xCF\xA4\xB7\xA4\xDE\xA4\xB9\xA1\xA3<br>\xCD\xF8\xCD\xD1\xBC\xD4\xA4\xAC\xBA\xEE\xC0\xAE\xA4\xB7\xA4\xBF\xA5\xD5\xA5\xA9\xA1\xBC\xA5\xE0\xA4\xCE\xC3\xCD\xA4\xF2\xCA\xDD\xC2\xB8\xA4\xB9\xA4\xEB\xA5\xC7\xA1\xBC\xA5\xBF\xA5\xB9\xA5\xE9\xA5\xA4\xA5\xB9\xA4\xCB\xCD\xF8\xCD\xD1\xA4\xC7\xA4\xAD\xA4\xDE\xA4\xB9\xA1\xA3", // ai 2026-06

